-- rollback_v640_fb_ai_filter_config: tắt cấu hình V640. Gỡ V641 trước (block đang gọi mã _v2 thì tắt mã sẽ làm block báo lỗi). Không xoá dòng (ai_log, kết quả engine
-- có thể đang trỏ tới); dấu hiệu FB53 bỏ khỏi facebook.error_signs.
BEGIN;
SET LOCAL lock_timeout = '3s';
DO $pre$
BEGIN
  IF EXISTS (SELECT 1 FROM public.auto_blocks WHERE code LIKE '%_ai_filter_v2%') THEN RAISE EXCEPTION 'Gỡ V640: còn block gọi mã _v2, gỡ V641 trước'; END IF;
END $pre$;
UPDATE public.ai_using SET is_active = false, updated_at = now() WHERE code IN ('fb_prepare_seeding_iterations_ai_filter_v2', 'fb_extract_data_from_group_posts_ai_filter_v2', 'fb_collect_group_comments_ai_filter_v2', 'fb_extract_data_from_search_posts_ai_filter_v2', 'fb_collect_search_post_comments_ai_filter_v2', 'fb_ai_content_filter_fallback');
UPDATE public.ai_prompt SET is_active = false, updated_at = now() WHERE code = 'find_data_meaning_check_v2';
UPDATE public.auto_outcome_policies SET is_active = false, is_delete = true, updated_at = now() WHERE error_code = 'err_fb_ai_filter_unavailable' AND source = 'v640';
UPDATE public.auto_error SET is_active = false, is_delete = true, updated_at = now() WHERE error_code = 'err_fb_ai_filter_unavailable';
UPDATE public.auto_system_settings SET value = $v640$[{"code":"err_fb_page_inbox_customer_not_found","source":"message","actions":["fb_message_page_inbox_customer"],"phases":[],"replaces":[],"texts":["Không tìm thấy khách hàng trong inbox page"]},{"code":"err_fb_page_inbox_wrong_conversation","source":"message","actions":["fb_message_page_inbox_customer"],"phases":[],"replaces":[],"texts":["Không tìm thấy đúng khách hàng trong inbox page"]},{"code":"err_fb_upload_form_changed","source":"message","actions":[],"phases":["before_send"],"replaces":[],"texts":["Cần đúng 1 input file trong form đăng bài, tìm thấy 0","Input trong form không nhận ảnh/video"]},{"code":"err_fb_group_cannot_post_unavailable","source":"page","actions":["fb_post_group"],"phases":[],"replaces":["err_fb_group_composer_editor_not_found"],"texts":["Bạn hiện không xem được nội dung này","This content isn't available right now"]},{"code":"err_fb_group_cannot_post_not_member","source":"page","actions":["fb_post_group"],"phases":[],"replaces":["err_fb_group_composer_editor_not_found"],"texts":["Tham gia nhóm","Join group"]},{"code":"err_fb_comment_box_not_found","source":"message","actions":["fb_comment"],"phases":[],"replaces":[],"texts":["waitForSelector timeout"]},{"code":"err_fb_page_inbox_identity_required","source":"message","actions":["fb_message_page_inbox_customer"],"phases":[],"replaces":["err_undefined"],"texts":["Facebook yêu cầu xác nhận danh tính trước khi Page gửi tin"]},{"code":"err_fb_page_inbox_cannot_reply_blocked_by_user","source":"message","actions":["fb_message_page_inbox_customer"],"phases":[],"replaces":["err_undefined"],"texts":["Page không gửi được tin cho người này nữa"]},{"code":"err_fb_page_inbox_message_box_not_found","source":"message","actions":["fb_message_page_inbox_customer"],"phases":[],"replaces":["err_undefined"],"texts":["Không tìm thấy ô để nhập tin nhắn"]},{"code":"err_fb_group_post_request_failed","source":"message","actions":["fb_post_group"],"phases":[],"replaces":[],"texts":["Facebook báo gặp sự cố khi đăng bài"]},{"code":"err_fb_group_post_upload_failed","source":"message","actions":["fb_post_group"],"phases":[],"replaces":[],"texts":["Facebook không tải được ảnh hoặc video lên"]},{"code":"err_fb_account_access_limited","source":"message","actions":["fb_post_group"],"phases":[],"replaces":[],"texts":["Facebook đang giới hạn quyền truy cập của tài khoản"]},{"code":"err_fb_messenger_recipient_cannot_access_chat","source":"message","actions":["fb_message_friend","fb_message_stranger"],"phases":[],"replaces":[],"texts":["Người này chưa đăng nhập Messenger nên chưa nhận được tin"]},{"code":"err_fb_messenger_unavailable_target_not_messageable","source":"message","actions":["fb_message_friend","fb_message_stranger"],"phases":[],"replaces":[],"texts":["Facebook chỉ cho nhắn tin khi đã kết bạn với người này"]}]$v640$, updated_at = now() WHERE key = 'facebook.error_signs' AND md5(value) = '3c9abdeca0782d4caf0f159637074d91';
DO $post$
BEGIN
  IF (SELECT md5(value) FROM public.auto_system_settings WHERE key = 'facebook.error_signs') IS DISTINCT FROM 'a8eb20650fc32f7541c6622b7f51caee' THEN RAISE EXCEPTION 'Gỡ V640: dòng facebook.error_signs chưa về bản cũ'; END IF;
END $post$;
COMMIT;
